-- generated by rice-effects (Settings > Services). Loaded last, so it wins.
-- no blur, no transparency
pcall(hl.config, { decoration = { blur = { enabled = false } } })
pcall(hl.config, { decoration = { active_opacity = 1.0, inactive_opacity = 1.0, fullscreen_opacity = 1.0 } })
pcall(hl.window_rule, { name = "rice-flat-opaque", match = { class = ".*" }, opacity = "1.0 override 1.0 override" })
-- gaming mode
pcall(hl.config, { animations = { enabled = false } })
pcall(hl.config, { decoration = { shadow = { enabled = false } } })
pcall(hl.config, { general = { gaps_in = 0, gaps_out = 0 } })
